// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }

    function testFuzz_property(address depositor, uint96 amount) public {
        vm.assume(depositor != address(0));
        vm.assume(amount > 0);

        Attacker attacker = new Attacker(c);

        vm.deal(depositor, amount);
        vm.prank(address(attacker));
        vm.deal(address(attacker), amount);
        attacker.depositToC{value: amount}();

        uint256 before = address(c).balance;

        vm.prank(address(attacker));
        bool ok;
        try attacker.triggerWithdraw() {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(address(c).balance == (ok ? before - amount : before));
    }
}

contract Attacker {
    Reentrance c;
    bool reentered = false;
    constructor(Reentrance _c) {
        c = _c;
    }

    function depositToC() external payable {
        c.addToBalance{value: msg.value}();
    }

    function triggerWithdraw() external {
        c.withdrawBalance();
    }

    receive() external payable {
        if (!reentered) {
            reentered = true;
            try c.withdrawBalance() {
            } catch {
            }
        }
    }
}
